/**
 * @license MIT
 * @origin 21st.dev / Agent Wiki (https://21st.dev)
 * @author 21st.dev & Machine-First Design Agent Wiki
 * @curated-by Machine-First Design Agent Wiki
 * Maintained under upstream open-source license terms.
 */

import * as React from "react";
import { cn } from "../lib/utils";
import {
  Monitor,
  Tablet,
  Smartphone,
  Code2,
  Eye,
  RotateCw,
  ExternalLink,
  Copy,
  Check,
  SplitSquareVertical,
} from "lucide-react";

export interface AiArtifactSandboxIframeProps extends React.HTMLAttributes<HTMLDivElement> {
  artifactTitle?: string;
  sourceCode: string;
  previewUrl?: string;
  defaultView?: "preview" | "code" | "split";
  versionTag?: string;
}

export function AiArtifactSandboxIframe({
  artifactTitle = "Component Sandbox Preview",
  sourceCode,
  previewUrl = "about:blank",
  defaultView = "preview",
  versionTag = "v1.2.0",
  className,
  ...props
}: AiArtifactSandboxIframeProps) {
  const [viewMode, setViewMode] = React.useState<"preview" | "code" | "split">(defaultView);
  const [deviceMode, setDeviceMode] = React.useState<"desktop" | "tablet" | "mobile">("desktop");
  const [copied, setCopied] = React.useState(false);
  const [isRefreshing, setIsRefreshing] = React.useState(false);

  const handleCopy = () => {
    navigator.clipboard.writeText(sourceCode);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handleRefresh = () => {
    setIsRefreshing(true);
    setTimeout(() => setIsRefreshing(false), 600);
  };

  return (
    <div
      className={cn(
        "flex flex-col w-full rounded-2xl border border-border bg-card text-card-foreground shadow-lg overflow-hidden",
        className
      )}
      role="region"
      aria-label={`Artifact Sandbox: ${artifactTitle}`}
      {...props}
    >
      {/* Top Toolbar */}
      <div className="flex flex-wrap items-center justify-between gap-2 px-4 py-2.5 bg-muted/40 border-b border-border">
        {/* Left: Title & Version */}
        <div className="flex items-center gap-2">
          <span className="font-semibold text-xs text-foreground">{artifactTitle}</span>
          <span className="px-2 py-0.5 rounded-md bg-primary/10 text-primary font-mono text-xs">
            {versionTag}
          </span>
        </div>

        {/* Center: Device Switcher (when in preview mode) */}
        {viewMode !== "code" && (
          <div className="flex items-center gap-1 p-1 rounded-xl bg-background border border-border">
            <button
              type="button"
              onClick={() => setDeviceMode("desktop")}
              aria-label="Desktop preview width"
              className={cn(
                "p-1.5 rounded-lg text-xs transition-colors focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring",
                deviceMode === "desktop" ? "bg-muted text-foreground" : "text-muted-foreground hover:text-foreground"
              )}
            >
              <Monitor className="h-3.5 w-3.5" aria-hidden="true" />
            </button>
            <button
              type="button"
              onClick={() => setDeviceMode("tablet")}
              aria-label="Tablet preview width (768px)"
              className={cn(
                "p-1.5 rounded-lg text-xs transition-colors focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring",
                deviceMode === "tablet" ? "bg-muted text-foreground" : "text-muted-foreground hover:text-foreground"
              )}
            >
              <Tablet className="h-3.5 w-3.5" aria-hidden="true" />
            </button>
            <button
              type="button"
              onClick={() => setDeviceMode("mobile")}
              aria-label="Mobile preview width (375px)"
              className={cn(
                "p-1.5 rounded-lg text-xs transition-colors focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring",
                deviceMode === "mobile" ? "bg-muted text-foreground" : "text-muted-foreground hover:text-foreground"
              )}
            >
              <Smartphone className="h-3.5 w-3.5" aria-hidden="true" />
            </button>
          </div>
        )}

        {/* Right: View Mode Toggle & Actions */}
        <div className="flex items-center gap-1.5">
          <div className="flex items-center gap-1 p-1 rounded-xl bg-background border border-border">
            <button
              type="button"
              onClick={() => setViewMode("preview")}
              className={cn(
                "inline-flex items-center gap-1 px-2.5 py-1 rounded-lg text-xs font-medium transition-colors focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring",
                viewMode === "preview" ? "bg-muted text-foreground font-semibold" : "text-muted-foreground hover:text-foreground"
              )}
            >
              <Eye className="h-3.5 w-3.5" aria-hidden="true" /> Preview
            </button>
            <button
              type="button"
              onClick={() => setViewMode("code")}
              className={cn(
                "inline-flex items-center gap-1 px-2.5 py-1 rounded-lg text-xs font-medium transition-colors focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring",
                viewMode === "code" ? "bg-muted text-foreground font-semibold" : "text-muted-foreground hover:text-foreground"
              )}
            >
              <Code2 className="h-3.5 w-3.5" aria-hidden="true" /> Code
            </button>
            <button
              type="button"
              onClick={() => setViewMode("split")}
              className={cn(
                "inline-flex items-center gap-1 px-2.5 py-1 rounded-lg text-xs font-medium transition-colors focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring",
                viewMode === "split" ? "bg-muted text-foreground font-semibold" : "text-muted-foreground hover:text-foreground"
              )}
            >
              <SplitSquareVertical className="h-3.5 w-3.5" aria-hidden="true" /> Split
            </button>
          </div>

          <button
            type="button"
            onClick={handleRefresh}
            aria-label="Refresh sandbox preview"
            className="p-2 rounded-xl border border-border bg-background hover:bg-muted text-muted-foreground hover:text-foreground transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
          >
            <RotateCw className={cn("h-3.5 w-3.5", isRefreshing && "animate-spin")} aria-hidden="true" />
          </button>

          <button
            type="button"
            onClick={handleCopy}
            aria-label={copied ? "Source code copied" : "Copy source code"}
            className="p-2 rounded-xl border border-border bg-background hover:bg-muted text-muted-foreground hover:text-foreground transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
          >
            {copied ? (
              <Check className="h-3.5 w-3.5 text-emerald-500" aria-hidden="true" />
            ) : (
              <Copy className="h-3.5 w-3.5" aria-hidden="true" />
            )}
          </button>
        </div>
      </div>

      {/* Sandbox Workspace Area */}
      <div className="relative flex flex-col md:flex-row w-full h-[520px] bg-muted/20 overflow-hidden">
        {/* Preview Frame Container */}
        {(viewMode === "preview" || viewMode === "split") && (
          <div
            className={cn(
              "flex-1 flex items-center justify-center p-6 transition-colors duration-200 overflow-auto",
              viewMode === "split" && "border-r border-border md:w-1/2"
            )}
          >
            <div
              className={cn(
                "relative h-full bg-background rounded-xl border border-border shadow-xl overflow-hidden transition-colors duration-200",
                deviceMode === "desktop"
                  ? "w-full"
                  : deviceMode === "tablet"
                  ? "w-[640px]"
                  : "w-[360px]"
              )}
            >
              {/* Fallback & Sandbox Frame */}
              <iframe
                title={artifactTitle}
                src={previewUrl}
                sandbox="allow-scripts allow-same-origin"
                className="w-full h-full border-0 bg-background"
              />
              <div className="absolute top-2 right-2 flex items-center gap-1.5 px-2 py-1 rounded-md bg-muted/80 backdrop-blur-xs border border-border text-[10px] text-muted-foreground font-mono">
                <span>{deviceMode === "desktop" ? "100%" : deviceMode === "tablet" ? "640px" : "360px"}</span>
              </div>
            </div>
          </div>
        )}

        {/* Code Editor View */}
        {(viewMode === "code" || viewMode === "split") && (
          <div
            className={cn(
              "flex-1 flex flex-col bg-card overflow-auto font-mono text-xs text-foreground p-4",
              viewMode === "split" && "md:w-1/2"
            )}
          >
            <pre className="overflow-x-auto leading-relaxed">
              <code>{sourceCode}</code>
            </pre>
          </div>
        )}
      </div>
    </div>
  );
}

/**
 * @license MIT
 * @origin Origin UI / Cult UI (https://originui.com)
 * @author Origin UI & Machine-First Design Agent Wiki
 * @curated-by Machine-First Design Agent Wiki
 * Maintained under upstream open-source license terms.
 */

import * as React from "react";
import { cn } from "../lib/utils";
import {
  Check,
  X,
  Edit3,
  GitCommit,
  FileCode,
  Sparkles,
  ChevronRight,
  ShieldCheck,
} from "lucide-react";

export interface DiffLine {
  type: "add" | "delete" | "normal";
  oldLineNumber?: number;
  newLineNumber?: number;
  content: string;
}

export interface AiHumanInTheLoopDiffProps extends React.HTMLAttributes<HTMLDivElement> {
  fileName?: string;
  diffLines?: DiffLine[];
  explanation?: string;
  onApprove?: () => void;
  onReject?: () => void;
  onModifyPrompt?: (feedback: string) => void;
}

export function AiHumanInTheLoopDiff({
  fileName = "components/ui/hero-section.tsx",
  diffLines = [
    { type: "normal", oldLineNumber: 12, newLineNumber: 12, content: "export function HeroSection() {" },
    { type: "delete", oldLineNumber: 13, content: "-   return <div className=\"bg-blue-600 p-4\">" },
    { type: "add", newLineNumber: 13, content: "+   return <div className=\"bg-card border border-border p-4\">" },
    { type: "normal", oldLineNumber: 14, newLineNumber: 14, content: "       <h1>Agent Wiki</h1>" },
    { type: "normal", oldLineNumber: 15, newLineNumber: 15, content: "     </div>" },
  ],
  explanation = "Remapped hardcoded indigo colors and arbitrary pixel padding to semantic design tokens (SLOP-001 & SLOP-007 compliant).",
  onApprove,
  onReject,
  onModifyPrompt,
  className,
  ...props
}: AiHumanInTheLoopDiffProps) {
  const [isModifying, setIsModifying] = React.useState(false);
  const [feedbackPrompt, setFeedbackPrompt] = React.useState("");

  const additions = diffLines.filter((l) => l.type === "add").length;
  const deletions = diffLines.filter((l) => l.type === "delete").length;

  const handleApprove = () => {
    onApprove?.();
  };

  const handleReject = () => {
    onReject?.();
  };

  const handleSendFeedback = () => {
    if (!feedbackPrompt.trim()) return;
    onModifyPrompt?.(feedbackPrompt);
    setIsModifying(false);
    setFeedbackPrompt("");
  };

  return (
    <div
      className={cn(
        "flex flex-col w-full rounded-2xl border border-border bg-card text-card-foreground shadow-xl overflow-hidden",
        className
      )}
      role="region"
      aria-label={`Human-in-the-loop review for ${fileName}`}
      {...props}
    >
      {/* Header bar */}
      <div className="flex items-center justify-between px-4 py-3 bg-muted/40 border-b border-border">
        <div className="flex items-center gap-2.5">
          <div className="flex items-center justify-center h-7 w-7 rounded-lg bg-primary/10 text-primary border border-primary/20">
            <FileCode className="h-4 w-4" aria-hidden="true" />
          </div>
          <div>
            <div className="flex items-center gap-2">
              <span className="font-mono text-xs font-semibold text-foreground">{fileName}</span>
              <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full bg-muted text-muted-foreground text-xs font-mono">
                <span className="text-emerald-500 font-semibold">+{additions}</span>
                <span className="text-destructive font-semibold">-{deletions}</span>
              </span>
            </div>
          </div>
        </div>

        <div className="flex items-center gap-1.5 text-xs text-muted-foreground">
          <ShieldCheck className="h-4 w-4 text-primary" aria-hidden="true" />
          <span>Human Gatekeeper Review</span>
        </div>
      </div>

      {/* Rationale explanation */}
      {explanation && (
        <div className="px-4 py-2.5 bg-primary/5 border-b border-primary/10 flex items-center gap-2 text-xs text-foreground">
          <Sparkles className="h-3.5 w-3.5 text-primary shrink-0" aria-hidden="true" />
          <span>{explanation}</span>
        </div>
      )}

      {/* Code Diff Display */}
      <div className="overflow-x-auto bg-muted/20 font-mono text-xs max-h-72">
        <table className="w-full border-collapse">
          <tbody>
            {diffLines.map((line, idx) => (
              <tr
                key={idx}
                className={cn(
                  "hover:bg-muted/40 transition-colors",
                  line.type === "add" && "bg-emerald-500/10 text-emerald-600 dark:text-emerald-400",
                  line.type === "delete" && "bg-destructive/10 text-destructive dark:text-destructive-foreground/90"
                )}
              >
                <td className="w-10 px-2 py-0.5 text-right text-muted-foreground/60 select-none border-r border-border/40">
                  {line.oldLineNumber || ""}
                </td>
                <td className="w-10 px-2 py-0.5 text-right text-muted-foreground/60 select-none border-r border-border/40">
                  {line.newLineNumber || ""}
                </td>
                <td className="px-3 py-0.5 whitespace-pre">
                  {line.content}
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {/* Modify Feedback Box */}
      {isModifying && (
        <div className="p-4 border-t border-border bg-card space-y-2">
          <label htmlFor="refine-prompt" className="text-xs font-semibold text-foreground">
            Refine Instructions / Request Modifications
          </label>
          <textarea
            id="refine-prompt"
            value={feedbackPrompt}
            onChange={(e) => setFeedbackPrompt(e.target.value)}
            placeholder="Tell the agent what to change (e.g., 'Use rounded-2xl cards instead')..."
            rows={2}
            className="w-full p-2.5 rounded-xl border border-border bg-background text-xs text-foreground placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring resize-none"
          />
          <div className="flex justify-end gap-2">
            <button
              type="button"
              onClick={() => setIsModifying(false)}
              className="px-3 py-1.5 rounded-xl border border-border text-xs text-muted-foreground hover:text-foreground transition-colors focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring"
            >
              Cancel
            </button>
            <button
              type="button"
              onClick={handleSendFeedback}
              disabled={!feedbackPrompt.trim()}
              className="px-3 py-1.5 rounded-xl bg-primary text-primary-foreground text-xs font-medium hover:bg-primary/90 disabled:opacity-50 transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
            >
              Send Refinement
            </button>
          </div>
        </div>
      )}

      {/* Action Footer */}
      {!isModifying && (
        <div className="flex items-center justify-between px-4 py-3 bg-muted/40 border-t border-border">
          <button
            type="button"
            onClick={() => setIsModifying(true)}
            className="inline-flex items-center gap-1.5 px-3 py-1.5 rounded-xl border border-border bg-background hover:bg-muted text-xs font-medium text-foreground transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
          >
            <Edit3 className="h-3.5 w-3.5 text-muted-foreground" aria-hidden="true" />
            Modify Prompt
          </button>

          <div className="flex items-center gap-2">
            <button
              type="button"
              onClick={handleReject}
              className="inline-flex items-center gap-1.5 px-3.5 py-1.5 rounded-xl border border-destructive/30 bg-destructive/10 text-destructive hover:bg-destructive/20 text-xs font-semibold transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
            >
              <X className="h-3.5 w-3.5" aria-hidden="true" />
              Reject Changes
            </button>

            <button
              type="button"
              onClick={handleApprove}
              className="inline-flex items-center gap-1.5 px-4 py-1.5 rounded-xl bg-primary text-primary-foreground hover:bg-primary/90 text-xs font-semibold shadow-xs transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2"
            >
              <Check className="h-3.5 w-3.5" aria-hidden="true" />
              Approve & Apply
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

/**
 * @license MIT
 * @origin Kokonut UI / Cult UI (https://kokonutui.com)
 * @author KokonutUI Team & Machine-First Design Agent Wiki
 * @curated-by Machine-First Design Agent Wiki
 * Maintained under upstream open-source license terms.
 */

import * as React from "react";
import { cn } from "../lib/utils";
import {
  Mic,
  MicOff,
  Paperclip,
  ArrowUp,
  Sparkles,
  ChevronDown,
  X,
  FileText,
  Image as ImageIcon,
  Command,
} from "lucide-react";

export interface AiPromptBarExpandedProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, "onSubmit"> {
  onSubmit?: (prompt: string, attachments: File[], model: string) => void;
  models?: Array<{ id: string; label: string; tag?: string }>;
  defaultModel?: string;
  placeholder?: string;
  maxTokens?: number;
  isLoading?: boolean;
}

export function AiPromptBarExpanded({
  onSubmit,
  models = [
    { id: "gpt-4o", label: "GPT-4o", tag: "Fast" },
    { id: "claude-3-7-sonnet", label: "Claude 3.7 Sonnet", tag: "Reasoning" },
    { id: "gemini-2-flash", label: "Gemini 2.0 Flash", tag: "Multimodal" },
  ],
  defaultModel = "claude-3-7-sonnet",
  placeholder = "Ask anything, type '/' for commands, or attach files...",
  maxTokens = 8192,
  isLoading = false,
  className,
  ...props
}: AiPromptBarExpandedProps) {
  const [prompt, setPrompt] = React.useState("");
  const [selectedModel, setSelectedModel] = React.useState(defaultModel);
  const [isRecording, setIsRecording] = React.useState(false);
  const [isModelDropdownOpen, setIsModelDropdownOpen] = React.useState(false);
  const [isSlashMenuOpen, setIsSlashMenuOpen] = React.useState(false);
  const [attachments, setAttachments] = React.useState<
    Array<{ id: string; name: string; size: string; type: "file" | "image" }>
  >([]);

  const textareaRef = React.useRef<HTMLTextAreaElement>(null);
  const fileInputRef = React.useRef<HTMLInputElement>(null);

  const estimatedTokens = React.useMemo(() => {
    return Math.max(1, Math.round(prompt.length / 4));
  }, [prompt]);

  const slashCommands = [
    { cmd: "/refactor", desc: "Refactor active code for clarity & performance" },
    { cmd: "/test", desc: "Generate comprehensive unit & integration tests" },
    { cmd: "/audit", desc: "Scan against 35 Anti-Slop & A11y rules" },
    { cmd: "/explain", desc: "Explain architecture and data flow in depth" },
  ];

  const handleKeyDown = (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
    if (e.key === "Enter" && !e.shiftKey) {
      e.preventDefault();
      handleSubmit();
    } else if (e.key === "Escape") {
      setIsSlashMenuOpen(false);
      setIsModelDropdownOpen(false);
    }
  };

  const handleTextChange = (e: React.ChangeEvent<HTMLTextAreaElement>) => {
    const val = e.target.value;
    setPrompt(val);
    if (val.endsWith("/")) {
      setIsSlashMenuOpen(true);
    } else if (isSlashMenuOpen && !val.includes("/")) {
      setIsSlashMenuOpen(false);
    }
  };

  const insertSlashCommand = (cmd: string) => {
    const withoutSlash = prompt.endsWith("/") ? prompt.slice(0, -1) : prompt;
    setPrompt(`${withoutSlash}${cmd} `);
    setIsSlashMenuOpen(false);
    textareaRef.current?.focus();
  };

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files) return;
    const newItems = Array.from(files).map((f) => ({
      id: Math.random().toString(36).substring(2, 9),
      name: f.name,
      size: `${(f.size / 1024).toFixed(1)} KB`,
      type: f.type.startsWith("image/") ? ("image" as const) : ("file" as const),
    }));
    setAttachments((prev) => [...prev, ...newItems]);
  };

  const removeAttachment = (id: string) => {
    setAttachments((prev) => prev.filter((a) => a.id !== id));
  };

  const handleSubmit = () => {
    if ((!prompt.trim() && attachments.length === 0) || isLoading) return;
    onSubmit?.(prompt, [], selectedModel);
    setPrompt("");
    setAttachments([]);
    setIsSlashMenuOpen(false);
  };

  return (
    <div
      className={cn(
        "relative flex flex-col w-full rounded-2xl border border-border bg-card text-card-foreground shadow-lg transition-colors",
        className
      )}
      {...props}
    >
      {/* Attachment Tray */}
      {attachments.length > 0 && (
        <div className="flex flex-wrap items-center gap-2 px-4 pt-3 pb-1 border-b border-border/40">
          {attachments.map((file) => (
            <div
              key={file.id}
              className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-lg bg-muted/60 text-xs font-medium text-foreground border border-border"
            >
              {file.type === "image" ? (
                <ImageIcon className="h-3.5 w-3.5 text-primary" aria-hidden="true" />
              ) : (
                <FileText className="h-3.5 w-3.5 text-primary" aria-hidden="true" />
              )}
              <span className="max-w-xs truncate">{file.name}</span>
              <span className="text-muted-foreground text-xs">({file.size})</span>
              <button
                type="button"
                onClick={() => removeAttachment(file.id)}
                aria-label={`Remove file ${file.name}`}
                className="ml-1 p-0.5 rounded-full hover:bg-muted text-muted-foreground hover:text-foreground focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring"
              >
                <X className="h-3 w-3" aria-hidden="true" />
              </button>
            </div>
          ))}
        </div>
      )}

      {/* Textarea Input */}
      <div className="relative px-4 pt-3 pb-2">
        <textarea
          ref={textareaRef}
          value={prompt}
          onChange={handleTextChange}
          onKeyDown={handleKeyDown}
          placeholder={placeholder}
          rows={3}
          className="w-full resize-none bg-transparent text-sm text-foreground placeholder:text-muted-foreground focus-visible:outline-none"
          aria-label="AI Prompt Input"
        />

        {/* Slash Commands Dropdown */}
        {isSlashMenuOpen && (
          <div
            className="absolute bottom-full left-4 mb-2 w-80 rounded-xl border border-border bg-popover p-1.5 shadow-xl z-50 text-popover-foreground animate-in fade-in-50"
            role="menu"
            aria-label="Slash Commands List"
          >
            <div className="px-2 py-1 text-xs font-semibold text-muted-foreground uppercase tracking-wider flex items-center gap-1">
              <Command className="h-3 w-3" aria-hidden="true" /> Commands
            </div>
            {slashCommands.map((item) => (
              <button
                key={item.cmd}
                type="button"
                onClick={() => insertSlashCommand(item.cmd)}
                className="w-full flex items-center justify-between px-2.5 py-1.5 rounded-lg text-xs hover:bg-accent hover:text-accent-foreground text-left transition-colors focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-ring"
              >
                <span className="font-mono font-semibold text-primary">{item.cmd}</span>
                <span className="text-muted-foreground text-xs">{item.desc}</span>
              </button>
            ))}
          </div>
        )}
      </div>

      {/* Control Bar Footer */}
      <div className="flex items-center justify-between px-4 py-2.5 border-t border-border/40 bg-muted/20 rounded-b-2xl">
        <div className="flex items-center gap-2">
          {/* Model Selector Button */}
          <div className="relative">
            <button
              type="button"
              onClick={() => setIsModelDropdownOpen((prev) => !prev)}
              aria-expanded={isModelDropdownOpen}
              aria-haspopup="listbox"
              aria-label="Select AI Model"
              className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-lg border border-border bg-background hover:bg-accent text-xs font-medium text-foreground transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
            >
              <Sparkles className="h-3.5 w-3.5 text-primary" aria-hidden="true" />
              <span>{models.find((m) => m.id === selectedModel)?.label || "Model"}</span>
              <ChevronDown className="h-3 w-3 text-muted-foreground" aria-hidden="true" />
            </button>

            {isModelDropdownOpen && (
              <div
                className="absolute bottom-full left-0 mb-1.5 w-56 rounded-xl border border-border bg-popover p-1 shadow-lg z-50 text-popover-foreground"
                role="listbox"
              >
                {models.map((m) => (
                  <button
                    key={m.id}
                    type="button"
                    onClick={() => {
                      setSelectedModel(m.id);
                      setIsModelDropdownOpen(false);
                    }}
                    role="option"
                    aria-selected={selectedModel === m.id}
                    className={cn(
                      "w-full flex items-center justify-between px-2.5 py-1.5 rounded-lg text-xs text-left transition-colors focus-visible:outline-none",
                      selectedModel === m.id
                        ? "bg-primary text-primary-foreground font-semibold"
                        : "hover:bg-accent hover:text-accent-foreground text-foreground"
                    )}
                  >
                    <span>{m.label}</span>
                    {m.tag && (
                      <span className="text-xs opacity-75">{m.tag}</span>
                    )}
                  </button>
                ))}
              </div>
            )}
          </div>

          {/* Attach Button */}
          <button
            type="button"
            onClick={() => fileInputRef.current?.click()}
            aria-label="Attach images or documents"
            className="p-1.5 rounded-lg hover:bg-muted text-muted-foreground hover:text-foreground transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
          >
            <Paperclip className="h-4 w-4" aria-hidden="true" />
          </button>
          <input
            ref={fileInputRef}
            type="file"
            multiple
            onChange={handleFileUpload}
            className="hidden"
            aria-hidden="true"
          />

          {/* Voice Input Toggle */}
          <button
            type="button"
            onClick={() => setIsRecording((prev) => !prev)}
            aria-label={isRecording ? "Stop voice recording" : "Start voice recording"}
            className={cn(
              "p-1.5 rounded-lg transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring",
              isRecording
                ? "bg-destructive text-destructive-foreground animate-pulse"
                : "hover:bg-muted text-muted-foreground hover:text-foreground"
            )}
          >
            {isRecording ? (
              <MicOff className="h-4 w-4" aria-hidden="true" />
            ) : (
              <Mic className="h-4 w-4" aria-hidden="true" />
            )}
          </button>
        </div>

        {/* Right Side: Token Counter & Send Button */}
        <div className="flex items-center gap-3">
          <span className="text-xs font-mono text-muted-foreground" aria-label="Estimated Tokens">
            ~{estimatedTokens}/{maxTokens} tok
          </span>

          <button
            type="button"
            onClick={handleSubmit}
            disabled={(!prompt.trim() && attachments.length === 0) || isLoading}
            aria-label="Send AI Prompt"
            className="inline-flex items-center justify-center h-8 w-8 rounded-xl bg-primary text-primary-foreground font-medium shadow-xs hover:bg-primary/90 disabled:opacity-40 disabled:pointer-events-none transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2"
          >
            <ArrowUp className="h-4 w-4" aria-hidden="true" />
          </button>
        </div>
      </div>
    </div>
  );
}

