              <p className="text-xs text-muted-foreground mt-1 max-w-sm">
                Connected to @design-wiki/mcp server. Autonomous tools ready for prompt synthesis.
              </p>
            </div>
          )}
        </main>
      </div>
    </div>
  );
}

