                if (val === undefined) {
                  return <td key={idx} className="py-2 px-3 text-center bg-muted/20" />;
                }
                return (
                  <td key={idx} className="p-1">
                    <div
                      className={cn(
                        "h-8 rounded-lg flex items-center justify-center font-mono text-xs transition-colors",
                        getCellColor(val)
                      )}
