              const startX = node.x + 130;
              const startY = node.y + 36;
              const endX = target.x;
              const endY = target.y + 36;
              const midX = (startX + endX) / 2;

              return (
                <path
                  key={`${node.id}-${target.id}`}
                  d={`M ${startX} ${startY} C ${midX} ${startY}, ${midX} ${endY}, ${endX} ${endY}`}
